// ====================================================//   ZN STORE — app.js — نسخة InfinityFree المُصلَحة// ===================================================='use strict';// ======= متغيرات عامة =======let currentUser     = null;let products        = [];let shippingData    = [];let cart            = JSON.parse(localStorage.getItem('zn_cart') || '[]');let currentProduct  = null;let currentProductQty = 1;let currentGalleryIdx = 0;let selectedDelivery  = '';let selectedPayment   = '';let selectedNetwork   = '';let selectedNetwork2  = '';let currentEditOrderId = '';let currentRatingProductId = '';let currentRatingOrderId   = '';let selectedRating  = 0;let searchTimeout   = null;let sounds          = {};let allCategories   = [];// ======= متغيرات التشغيل في الخلفية (InfinityFree Fix) =======let backgroundPollingInterval = null;let lastNotifCount = 0;const POLLING_INTERVAL = 60000; // كل 60 ثانيةconst API = '/api';// ======= الأصوات =======function initSounds() {    try {        sounds.click   = new Howl({ src: ['https://assets.mixkit.co/active_storage/sfx/2997/2997-preview.mp3'], volume: 0.2 });        sounds.add     = new Howl({ src: ['https://assets.mixkit.co/active_storage/sfx/1435/1435-preview.mp3'], volume: 0.5 });        sounds.success = new Howl({ src: ['https://assets.mixkit.co/active_storage/sfx/2013/2013-preview.mp3'], volume: 0.5 });        sounds.error   = new Howl({ src: ['https://assets.mixkit.co/active_storage/sfx/2220/2220-preview.mp3'], volume: 0.4 });        sounds.cashier = new Howl({ src: ['https://assets.mixkit.co/active_storage/sfx/1434/1434-preview.mp3'], volume: 0.5 });        sounds.wallet  = new Howl({ src: ['https://assets.mixkit.co/active_storage/sfx/1434/1434-preview.mp3'], volume: 0.6 });    } catch(e) {}}function playSound(name) {    try { if (sounds[name]) sounds[name].play(); } catch(e) {}}// ======= Ripple =======function triggerRipple(e) {    try {        const target = e.currentTarget || e.target;        if (!target) return;        const rect = target.getBoundingClientRect();        const r = document.createElement('div');        r.className = 'ripple';        const size = Math.max(rect.width, rect.height);        r.style.cssText = `width:${size}px;height:${size}px;left:${(e.clientX||rect.left+rect.width/2)-rect.left-size/2}px;top:${(e.clientY||rect.top+rect.height/2)-rect.top-size/2}px`;        target.style.position = 'relative'; target.style.overflow = 'hidden';        target.appendChild(r);        setTimeout(() => r.remove(), 700);    } catch(ex) {}}// ======= API =======// InfinityFree Shared Hosting: السيرفر قد يكون "نائماً" بعد خمول (Cold Start)// نستخدم retry تلقائي مع timeout مناسب لإيقاظهasync function apiCallOnce(data, timeoutMs) {    const fd = new FormData();    Object.entries(data).forEach(([k, v]) => {        if (v !== undefined && v !== null) fd.append(k, String(v));    });    const token = localStorage.getItem('zn_auth_token');    if (token) fd.append('auth_token', token);    const noCacheActions = ['getProducts','getProduct','searchProducts'];    if (noCacheActions.includes(data.action)) fd.append('_t', Date.now());    const headers = {};    if (token) headers['X-Auth-Token'] = token;    const controller = new AbortController();    const timer = setTimeout(() => controller.abort(), timeoutMs);    try {        const res = await fetch(API, {            method: 'POST',            body: fd,            cache: 'no-store',            headers,            signal: controller.signal        });        clearTimeout(timer);        if (!res.ok) throw new Error('HTTP ' + res.status);        return await res.json();    } catch(e) {        clearTimeout(timer);        throw e;    }}async function apiCall(data, retries = 3) {    // timeout: 25s للمحاولة الأولى، 30s للتالية (لإيقاظ السيرفر على InfinityFree)    const timeouts = [25000, 30000, 30000];    let lastErr;    for (let i = 0; i < retries; i++) {        try {            return await apiCallOnce(data, timeouts[i] || 30000);        } catch(e) {            lastErr = e;            const msg = (e.message || '').toLowerCase();            const isNet = e.name === 'AbortError' || msg.includes('fetch') ||                          msg.includes('network') || msg.includes('failed') ||                          msg.includes('load');            if (isNet && i < retries - 1) {                await new Promise(r => setTimeout(r, 3000));                continue;            }            break;        }    }    throw lastErr;}// ======= Toast =======function showToast(message, type = 'info') {    const icons  = { success:'✅', error:'❌', warning:'⚠️', info:'ℹ️' };    const colors = { success:'#10b981', error:'#ef4444', warning:'#f59e0b', info:'#3b82f6' };    const t = document.getElementById('toastContainer');    if (!t) return;    const div = document.createElement('div');    div.className = 'toast show';    div.style.cssText = `border-left:3px solid ${colors[type]||colors.info}`;    div.innerHTML = `<span style="font-size:1rem">${icons[type]||'📢'}</span><span style="flex:1;font-size:0.88rem">${message}</span>`;    t.appendChild(div);    if (type === 'success') playSound('success');    else if (type === 'error') playSound('error');    setTimeout(() => { div.classList.remove('show'); setTimeout(() => div.remove(), 400); }, 3500);}// ======= تحميل =======function hideLoading() {    if (typeof window.hideLoadingWithPortal === 'function') {        window.hideLoadingWithPortal(() => {            const ls = document.getElementById('loadingScreen');            if (ls) ls.remove();        });    } else {        const ls = document.getElementById('loadingScreen');        if (ls) { ls.style.opacity = '0'; setTimeout(() => ls.remove(), 600); }    }}// ======= مصادقة =======function switchAuthTab(tab) {    playSound('click');    document.querySelectorAll('.auth-tab').forEach(t => t.classList.remove('active'));    document.querySelectorAll('.auth-form').forEach(f => f.classList.remove('active'));    const tabs = { login: 0, register: 1, forgot: 2 };    document.querySelectorAll('.auth-tab')[tabs[tab] ?? 0]?.classList.add('active');    const formMap = { login: 'loginForm', register: 'registerForm', forgot: 'forgotForm' };    document.getElementById(formMap[tab])?.classList.add('active');}function togglePassword(inputId, btn) {    const inp = document.getElementById(inputId);    if (!inp) return;    const show = inp.type === 'password';    inp.type = show ? 'text' : 'password';    btn.innerHTML = `<i class="fas fa-eye${show ? '-slash' : ''}"></i>`;}async function handleLogin() {    const phone    = document.getElementById('loginPhone').value.trim();    const pass     = document.getElementById('loginPassword').value;    const remember = document.getElementById('rememberMe')?.checked || false;    if (!phone || !pass) { showToast('أدخل رقم الهاتف وكلمة المرور', 'error'); return; }    const btn = document.getElementById('loginBtn');    btn.disabled = true;    btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> جاري الاتصال...';    try {        // === خطوة 1: إيقاظ السيرفر أولاً (InfinityFree Fix) ===        // ننتظر الـ ping قبل إرسال بيانات الدخول        btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> جاري الاتصال بالسيرفر...';        try {            await apiCallOnce({ action: 'ping' }, 20000);        } catch(e) {            // السيرفر لم يرد على الـ ping — نحاول الدخول على أي حال        }        // === خطوة 2: إرسال بيانات الدخول ===        btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> جاري التحقق...';        const res = await apiCall({ action: 'login', phone, password: pass, remember: remember ? '1' : '0' });        if (res.success) {            currentUser = res.data.user;            if (res.data.token) {                localStorage.setItem('zn_auth_token', res.data.token);            }            if (remember) {                localStorage.setItem('zn_auth_phone', phone);                localStorage.setItem('zn_remember_me', '1');            } else {                localStorage.setItem('zn_auth_phone', phone);                localStorage.removeItem('zn_remember_me');            }            playSound('success');            await showApp();        } else {            showToast(res.message || 'بيانات خاطئة', 'error');        }    } catch(e) {        const msg = (e.message || '').toLowerCase();        const isNet = e.name === 'AbortError' || msg.includes('fetch') ||                      msg.includes('network') || msg.includes('failed') || msg.includes('load');        if (isNet) {            showToast('⏳ السيرفر مشغول، انتظر 15 ثانية وأعد المحاولة', 'warning');        } else {            showToast('تعذر الاتصال بالسيرفر، حاول مجدداً', 'error');        }    } finally {        btn.disabled = false;        btn.innerHTML = '<i class="fas fa-sign-in-alt"></i> دخول';    }}async function handleRegister() {    const name  = document.getElementById('regName').value.trim();    const phone = document.getElementById('regPhone').value.trim();    const pass  = document.getElementById('regPassword').value;    const conf  = document.getElementById('regPasswordConfirm').value;    if (!name || !phone || !pass) { showToast('يرجى ملء جميع الحقول', 'error'); return; }    if (pass !== conf) { showToast('كلمتا المرور غير متطابقتين', 'error'); return; }    if (pass.length < 6) { showToast('كلمة المرور قصيرة (6 أحرف على الأقل)', 'error'); return; }    const btn = document.getElementById('registerBtn');    btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';    try {        const res = await apiCall({ action: 'register', name, phone, password: pass });        if (res.success) {            currentUser = res.data.user;            // === حفظ التوكن الذي يُنشأ تلقائياً عند التسجيل ===            if (res.data.token) {                localStorage.setItem('zn_auth_token', res.data.token);                localStorage.setItem('zn_auth_phone', phone);            }            playSound('success');            await showApp();        } else {            showToast(res.message || 'خطأ في التسجيل', 'error');        }    } catch(e) {        showToast('خطأ في الاتصال', 'error');    } finally {        btn.disabled = false;        btn.innerHTML = '<i class="fas fa-user-plus"></i> إنشاء حساب';    }}async function handleLogout() {    if (!confirm('هل تريد تسجيل الخروج؟')) return;    try { await apiCall({ action: 'logout' }); } catch(e) {}    // === مسح كل بيانات الجلسة ===    localStorage.removeItem('zn_auth_token');    localStorage.removeItem('zn_auth_phone');    localStorage.removeItem('zn_remember_me');    // إيقاف التشغيل في الخلفية    stopBackgroundPolling();    currentUser = null;    document.getElementById('mainApp').classList.remove('visible');    document.getElementById('authScreen').classList.remove('hidden');}async function sendOTP() {    const phone = document.getElementById('forgotPhone').value.trim();    if (!phone) { showToast('أدخل رقم الهاتف', 'error'); return; }    const btn = document.getElementById('sendOtpBtn');    btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';    try {        const res = await apiCall({ action: 'requestPasswordReset', phone });        if (res.success) {            showToast('تم إرسال الرمز', 'success');            document.getElementById('forgotStep1').style.display = 'none';            document.getElementById('forgotStep2').style.display = 'block';        } else { showToast(res.message || 'خطأ', 'error'); }    } catch(e) { showToast('خطأ في الاتصال', 'error'); }    finally { btn.disabled = false; btn.innerHTML = '<i class="fas fa-paper-plane"></i> إرسال رمز التحقق'; }}function otpInputHandler(input, idx) {    input.value = input.value.replace(/\D/, '');    if (input.value && idx < 5) document.getElementById('otp' + (idx + 1))?.focus();}async function verifyOTP() {    const code = [0,1,2,3,4,5].map(i => document.getElementById('otp'+i).value).join('');    if (code.length < 6) { showToast('أدخل الرمز كاملاً', 'error'); return; }    const btn = document.getElementById('verifyOtpBtn');    btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';    try {        const res = await apiCall({ action: 'verifyResetCode', code });        if (res.success) {            showToast('تم التحقق', 'success');            document.getElementById('forgotStep2').style.display = 'none';            document.getElementById('forgotStep3').style.display = 'block';        } else { showToast(res.message || 'رمز خاطئ', 'error'); }    } catch(e) { showToast('خطأ في الاتصال', 'error'); }    finally { btn.disabled = false; btn.innerHTML = '<i class="fas fa-check"></i> تحقق'; }}async function resetPassword() {    const newP = document.getElementById('newPassword').value;    const conf = document.getElementById('newPasswordConfirm').value;    if (!newP || newP.length < 6) { showToast('كلمة المرور قصيرة', 'error'); return; }    if (newP !== conf) { showToast('كلمتا المرور غير متطابقتين', 'error'); return; }    const btn = document.getElementById('resetPasswordBtn');    btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';    try {        const res = await apiCall({ action: 'resetPassword', new_password: newP });        if (res.success) {            showToast('تم تعيين كلمة المرور الجديدة', 'success');            switchAuthTab('login');        } else { showToast(res.message || 'خطأ', 'error'); }    } catch(e) { showToast('خطأ في الاتصال', 'error'); }    finally { btn.disabled = false; btn.innerHTML = '<i class="fas fa-key"></i> تعيين كلمة مرور جديدة'; }}// ======= بدء التطبيق =======async function showApp() {    document.getElementById('authScreen').classList.add('hidden');    document.getElementById('mainApp').classList.add('visible');    updateUserUI();    await loadShipping();    await loadAllCategories();    await loadProducts();    await loadNotifCount();    updateCartBadge();    // === تشغيل الـ Polling في الخلفية ===    startBackgroundPolling();}function updateUserUI() {    if (!currentUser) return;    const initial = (currentUser.name || 'م')[0];    ['userAvatarText'].forEach(id => {        const el = document.getElementById(id);        if (el) el.textContent = initial;    });    const profileAvatar = document.getElementById('profileAvatar');    const profileName   = document.getElementById('profileName');    const profilePhone  = document.getElementById('profilePhone');    if (profileAvatar) profileAvatar.textContent = initial;    if (profileName)   profileName.textContent   = currentUser.name;    if (profilePhone)  profilePhone.textContent  = currentUser.phone;    renderUserLevelBadge(currentUser.level || 'none');}function renderUserLevelBadge(level) {    const badges = {        none:    { cls:'level-none',    icon:'⭕', name:'عادي' },        bronze:  { cls:'level-bronze',  icon:'🥉', name:'برونزي' },        gold:    { cls:'level-gold',    icon:'🥇', name:'ذهبي' },        diamond: { cls:'level-diamond', icon:'💎', name:'ألماسي' }    };    const b = badges[level] || badges.none;    const html = `<span class="level-badge ${b.cls}">${b.icon} ${b.name}${level !== 'none' ? ' <i class="fas fa-check-circle verified-badge-icon" style="font-size:0.65rem"></i>' : ''}</span>`;    ['profileLevelBadge', 'userLevelBadgeWallet'].forEach(id => {        const el = document.getElementById(id);        if (el) el.innerHTML = html;    });}// ======================================================//   التشغيل في الخلفية — Polling (InfinityFree Fix)//   InfinityFree لا يدعم Cron Jobs، نستخدم Polling//   من جهة العميل بدلاً من ذلك// ======================================================function startBackgroundPolling() {    // إيقاف أي polling قديم    stopBackgroundPolling();    backgroundPollingInterval = setInterval(async () => {        if (!currentUser) return;        try {            // 1. تحديث عدد الإشعارات            await loadNotifCount();            // 2. تجديد بيانات المستخدم (يُجدد التوكن من جهة السيرفر أيضاً)            const res = await apiCall({ action: 'getUserData' });            if (res.success && res.data.user) {                const oldLevel = currentUser.level;                currentUser = res.data.user;                // إذا تغير المستوى — أشعر المستخدم                if (oldLevel && oldLevel !== currentUser.level) {                    updateUserUI();                }            } else if (!res.success) {                // === الجلسة انتهت — حاول إعادة الدخول بالتوكن ===                await tryReauthenticate();            }        } catch(e) {            // تجاهل الأخطاء في الخلفية        }    }, POLLING_INTERVAL);    // مزامنة عند العودة للتطبيق (من الخلفية)    document.addEventListener('visibilitychange', handleVisibilityChange);}function stopBackgroundPolling() {    if (backgroundPollingInterval) {        clearInterval(backgroundPollingInterval);        backgroundPollingInterval = null;    }    document.removeEventListener('visibilitychange', handleVisibilityChange);}async function handleVisibilityChange() {    if (document.visibilityState === 'visible' && currentUser) {        // المستخدم عاد للتطبيق — تحقق من الجلسة فوراً        try {            const res = await apiCall({ action: 'getUserData' });            if (res.success && res.data.user) {                currentUser = res.data.user;                updateUserUI();                await loadNotifCount();            } else {                // حاول إعادة المصادقة                await tryReauthenticate();            }        } catch(e) {}    }}async function tryReauthenticate() {    const savedToken = localStorage.getItem('zn_auth_token');    if (!savedToken) {        // لا يوجد توكن — أخرج المستخدم        forceLogout();        return;    }    try {        const tokenRes = await apiCall({ action: 'loginWithToken', auth_token: savedToken });        if (tokenRes.success) {            currentUser = tokenRes.data.user;            updateUserUI();        } else {            // التوكن منتهي — أخرج المستخدم            forceLogout();        }    } catch(e) {}}function forceLogout() {    // تسجيل خروج إجباري عند انتهاء الجلسة والتوكن    stopBackgroundPolling();    localStorage.removeItem('zn_auth_token');    // لا نمسح رقم الهاتف لتسهيل إعادة الدخول    currentUser = null;    const mainApp    = document.getElementById('mainApp');    const authScreen = document.getElementById('authScreen');    if (mainApp)    mainApp.classList.remove('visible');    if (authScreen) {        authScreen.classList.remove('hidden');        showToast('انتهت جلستك، يرجى إعادة تسجيل الدخول', 'warning');    }}// ======= التنقل =======function navigateTo(page) {    playSound('click');    document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));    document.querySelectorAll('.nav-item').forEach(n => n.classList.remove('active'));    const pageEl = document.getElementById('page-' + page);    const navEl  = document.getElementById('nav-' + page);    if (pageEl) { pageEl.classList.add('active'); } else { return; }    if (navEl)  navEl.classList.add('active');    window.scrollTo({ top: 0, behavior: 'smooth' });    if (page === 'orders')        loadMyOrders();    if (page === 'wallet')        loadWallet();    if (page === 'notifications') loadNotifications();    if (page === 'profile')       refreshProfile();    if (page === 'howto')         loadShippingInHowto();}// ======= الشحن =======async function loadShipping() {    try {        const res = await apiCall({ action: 'getShippingPrices' });        if (res.success) shippingData = res.data.shipping || [];    } catch(e) {}    populateWilayaSelect();}function populateWilayaSelect() {    const sel = document.getElementById('checkoutWilaya');    if (!sel) return;    sel.innerHTML = '<option value="">-- اختر الولاية --</option>';    shippingData.forEach(w => {        sel.innerHTML += `<option value="${w.name}">${w.name}</option>`;    });}function getWilayaData(name) {    return shippingData.find(w => w.name === name) || null;}function updateShippingPrice() {    const wilaya = document.getElementById('checkoutWilaya').value;    const w = getWilayaData(wilaya);    const officeEl = document.getElementById('officePrice');    const homeEl   = document.getElementById('homePrice');    if (officeEl) officeEl.textContent = w ? formatNum(w.office) + ' دج' : '-';    if (homeEl)   homeEl.textContent   = w ? formatNum(w.home)   + ' دج' : '-';    updateCheckoutSummary();}function selectDelivery(type) {    selectedDelivery = type;    ['deliveryOfficeOpt','deliveryHomeOpt'].forEach(id => {        document.getElementById(id)?.classList.remove('selected');    });    document.getElementById(type === 'office' ? 'deliveryOfficeOpt' : 'deliveryHomeOpt')?.classList.add('selected');    const ag = document.getElementById('addressGroup');    if (ag) ag.style.display = type === 'home' ? 'block' : 'none';    updateCheckoutSummary();}// ======= الفئات =======async function loadAllCategories() {    try {        const res = await apiCall({ action: 'getCategories' });        if (res.success) allCategories = res.data.categories || [];    } catch(e) {}}function renderCategories(prods) {    const container = document.getElementById('categoriesContainer');    if (!container) return;    const usedCats = new Set(prods.map(p => p.category));    const displayCats = allCategories.length ? allCategories : [...usedCats];    const chips = displayCats.map(cat => {        const count = prods.filter(p => p.category === cat).length;        return `<div class="category-chip" onclick="filterByCategory('${cat}',this)" style="${count===0?'opacity:0.5':''}">            <span>${cat}</span>${count > 0 ? `<span style="font-size:0.65rem;margin-right:0.2rem;color:rgba(212,175,55,0.7)">(${count})</span>` : ''}        </div>`;    }).join('');    container.innerHTML = `        <div class="category-chip active" onclick="filterByCategory('all',this)">            <span>🏪 الكل</span>        </div>        ${chips}    `;}function filterByCategory(cat, el) {    playSound('click');    document.querySelectorAll('.category-chip').forEach(c => c.classList.remove('active'));    el.classList.add('active');    const filtered = cat === 'all' ? products : products.filter(p => p.category === cat);    renderProducts(filtered);}// ======= المنتجات =======async function loadProducts(category = 'all') {    try {        const res = await apiCall({ action: 'getProducts', category });        if (res.success) {            products = res.data.products || [];            renderProducts(products);            renderCategories(products);        }    } catch(e) { showToast('خطأ في تحميل المنتجات', 'error'); }}function renderProducts(prods) {    const grid = document.getElementById('productsGrid');    const countEl = document.getElementById('productsCount');    if (!grid) return;    if (countEl) countEl.textContent = prods.length + ' منتج';    if (!prods.length) {        grid.innerHTML = `<div class="empty-state" style="grid-column:1/-1"><div class="empty-icon">📦</div><div class="empty-title">لا توجد منتجات في هذه الفئة</div></div>`;        return;    }    grid.innerHTML = prods.map(p => createProductCard(p)).join('');}function createProductCard(p) {    const img = p.images && p.images[0]        ? `<img src="${p.images[0]}" alt="${p.title}" loading="lazy" onerror="this.parentElement.innerHTML='<div class=product-img-placeholder>🛍️</div>'">`        : `<div class="product-img-placeholder">🛍️</div>`;    const badge   = p.out_of_stock ? '<div class="product-badge">نفذ</div>' : '';    const btnText  = p.out_of_stock ? '<i class="fas fa-times-circle"></i> نفذ المنتج' : '<i class="fas fa-cart-plus"></i> أضف للسلة';    const btnClass = p.out_of_stock ? 'add-to-cart-btn out-of-stock' : 'add-to-cart-btn';    return `        <div class="product-card animate-fadeInUp" onclick="openProductModal('${p.id}')">            <div class="product-img-wrapper">${img}${badge}</div>            <div class="product-info">                <div class="product-title">${p.title}</div>                <div class="product-price">${formatNum(p.price)} <span class="currency">دج</span></div>                <button class="${btnClass}" ${p.out_of_stock ? 'disabled' : ''}                    onclick="event.stopPropagation();${p.out_of_stock ? '' : `quickAddToCart('${p.id}')`}">${btnText}</button>            </div>        </div>`;}// ======= مودال المنتج =======function openProductModal(productId) {    playSound('click');    const p = products.find(x => x.id === productId);    if (!p) return;    currentProduct = p; currentProductQty = 1; currentGalleryIdx = 0;    document.getElementById('productModalTitle').textContent = p.title;    document.getElementById('productModalName').textContent  = p.title;    document.getElementById('productModalPrice').textContent = formatNum(p.price) + ' دج';    document.getElementById('productModalDesc').textContent  = p.description || '';    document.getElementById('productQty').textContent        = '1';    const gallery = document.getElementById('productModalGallery');    const mainImg = document.getElementById('productModalMainImg');    const thumbs  = document.getElementById('productModalThumbs');    if (p.images && p.images.length) {        mainImg.src = p.images[0];        mainImg.style.display = 'block';        gallery.querySelector('.prev').style.display = p.images.length > 1 ? 'flex' : 'none';        gallery.querySelector('.next').style.display = p.images.length > 1 ? 'flex' : 'none';        thumbs.innerHTML = p.images.map((img, i) =>            `<div class="gallery-thumb ${i===0?'active':''}" onclick="setGalleryImage(${i})" style="background-image:url('${img}')"></div>`        ).join('');    } else {        mainImg.src = ''; mainImg.style.display = 'none';        thumbs.innerHTML = '';    }    const ratings = p.ratings || [];    if (ratings.length) {        const avg = ratings.reduce((s, r) => s + r.rating, 0) / ratings.length;        document.getElementById('productModalRating').innerHTML =            `<div style="color:#ffd700;font-size:0.9rem">${'★'.repeat(Math.round(avg))}${'☆'.repeat(5 - Math.round(avg))} <span style="color:rgba(224,224,224,.6);font-size:0.78rem">(${ratings.length})</span></div>`;    } else { document.getElementById('productModalRating').innerHTML = ''; }    const addBtn = document.getElementById('productModalAddBtn');    if (p.out_of_stock) {        addBtn.disabled = true;        addBtn.innerHTML = '<i class="fas fa-times-circle"></i> نفذ المنتج';    } else {        addBtn.disabled = false;        addBtn.innerHTML = '<i class="fas fa-cart-plus"></i> إضافة للسلة';    }    const ratSection = document.getElementById('productRatingsSection');    if (ratSection) {        let html = '<div class="product-actions-bar">';        html += `<button class="btn-action-prod" onclick="copyProductText('${p.id}','title')"><i class="fas fa-copy"></i> نسخ العنوان</button>`;        html += `<button class="btn-action-prod" onclick="copyProductText('${p.id}','desc')"><i class="fas fa-align-left"></i> نسخ الوصف</button>`;        if (p.images && p.images.length) {            html += `<button class="btn-action-prod" onclick="saveProductImages('${p.id}')"><i class="fas fa-download"></i> حفظ الصور (${p.images.length})</button>`;        }        html += '</div>';        ratSection.innerHTML = html;    }    openModal('productModal');}// ======= نسخ نص المنتج =======function copyProductText(productId, type) {    const p = products.find(x => x.id === productId);    if (!p) return;    playSound('click');    const text  = type === 'title' ? p.title : (p.description || '');    const label = type === 'title' ? 'العنوان' : 'الوصف';    const doFallback = () => {        const ta = document.createElement('textarea');        ta.value = text; ta.style.cssText = 'position:fixed;opacity:0;pointer-events:none';        document.body.appendChild(ta); ta.focus(); ta.select();        try { document.execCommand('copy'); showToast('✅ تم نسخ ' + label, 'success'); } catch(e) {}        document.body.removeChild(ta);    };    if (navigator.clipboard && navigator.clipboard.writeText) {        navigator.clipboard.writeText(text)            .then(() => showToast('✅ تم نسخ ' + label, 'success'))            .catch(() => doFallback());    } else { doFallback(); }}// ======= حفظ صور المنتج =======async function saveProductImages(productId) {    const p = products.find(x => x.id === productId);    if (!p || !p.images || !p.images.length) return;    showToast('⬇️ جاري تحميل ' + p.images.length + ' صورة...', 'info');    const safeName = (p.title || 'product').replace(/[^\u0600-\u06FFa-zA-Z0-9]/g, '_').slice(0, 30);    let saved = 0;    for (let i = 0; i < p.images.length; i++) {        const imgUrl  = p.images[i];        const fileName = safeName + '_' + (i + 1) + '.jpg';        let done = false;        if (!done) {            try {                const resp = await fetch(imgUrl, { mode: 'cors', cache: 'no-store' });                if (resp.ok) {                    const blob = await resp.blob();                    const blobUrl = URL.createObjectURL(blob);                    const a = document.createElement('a');                    a.href = blobUrl; a.download = fileName;                    document.body.appendChild(a); a.click();                    document.body.removeChild(a);                    setTimeout(() => URL.revokeObjectURL(blobUrl), 3000);                    saved++; done = true;                }            } catch(e) {}        }        if (!done) {            try {                const proxyUrl = API + '?action=downloadProxy&url=' + encodeURIComponent(imgUrl);                const resp2 = await fetch(proxyUrl, { cache: 'no-store' });                if (resp2.ok && resp2.headers.get('content-type')?.startsWith('image')) {                    const blob2 = await resp2.blob();                    const blobUrl2 = URL.createObjectURL(blob2);                    const a2 = document.createElement('a');                    a2.href = blobUrl2; a2.download = fileName;                    document.body.appendChild(a2); a2.click();                    document.body.removeChild(a2);                    setTimeout(() => URL.revokeObjectURL(blobUrl2), 3000);                    saved++; done = true;                }            } catch(e) {}        }        if (!done) { window.open(imgUrl, '_blank'); saved++; }        if (p.images.length > 1) await new Promise(r => setTimeout(r, 800));    }    playSound('success');    showToast('✅ تم حفظ ' + saved + ' صورة — تحقق من مجلد التنزيلات', 'success');}function setGalleryImage(idx) {    const p = currentProduct;    if (!p || !p.images) return;    currentGalleryIdx = idx;    document.getElementById('productModalMainImg').src = p.images[idx];    document.querySelectorAll('.gallery-thumb').forEach((t, i) => t.classList.toggle('active', i === idx));}function galleryNav(dir) {    const p = currentProduct;    if (!p || !p.images || p.images.length < 2) return;    currentGalleryIdx = (currentGalleryIdx + dir + p.images.length) % p.images.length;    setGalleryImage(currentGalleryIdx);}function changeProductQty(delta) {    currentProductQty = Math.max(1, Math.min(10, currentProductQty + delta));    document.getElementById('productQty').textContent = currentProductQty;}function addCurrentProductToCart() {    if (!currentProduct || currentProduct.out_of_stock) return;    addToCart(currentProduct, currentProductQty);    closeModal('productModal');}function quickAddToCart(productId) {    const p = products.find(x => x.id === productId);    if (!p || p.out_of_stock) return;    addToCart(p, 1);}function addToCart(product, qty = 1) {    const existing = cart.find(c => c.id === product.id);    if (existing) {        existing.quantity = Math.min(10, existing.quantity + qty);    } else {        cart.push({ id: product.id, title: product.title, price: product.price,                    image: (product.images || [])[0] || '', quantity: qty });    }    localStorage.setItem('zn_cart', JSON.stringify(cart));    updateCartBadge();    showToast('تمت الإضافة للسلة 🛒', 'success');    playSound('add');    const badge = document.getElementById('cartBadge');    if (badge) { badge.classList.add('cart-add-anim'); setTimeout(() => badge.classList.remove('cart-add-anim'), 500); }}function updateCartBadge() {    const total = cart.reduce((s, c) => s + c.quantity, 0);    const badge = document.getElementById('cartBadge');    if (!badge) return;    badge.textContent = total;    badge.style.display = total > 0 ? 'flex' : 'none';}function openCart() {    playSound('click');    renderCart();    openModal('cartModal');}function renderCart() {    const content = document.getElementById('cartContent');    const footer  = document.getElementById('cartFooter');    if (!content) return;    if (!cart.length) {        content.innerHTML = `<div class="empty-state"><div class="empty-icon">🛒</div><div class="empty-title">السلة فارغة</div><div class="empty-desc">أضف منتجات للمتابعة</div></div>`;        if (footer) footer.style.display = 'none';        return;    }    const subtotal = cart.reduce((s, c) => s + c.price * c.quantity, 0);    content.innerHTML = cart.map(item => `        <div style="display:flex;gap:1rem;padding:1rem;background:var(--color-black-medium);border:var(--border-gold);border-radius:var(--radius-md);align-items:center;margin-bottom:0.75rem;">            <div style="width:70px;height:70px;border-radius:var(--radius-sm);background:var(--color-black-dark);flex-shrink:0;overflow:hidden;display:flex;align-items:center;justify-content:center;">                ${item.image ? `<img src="${item.image}" alt="" style="width:100%;height:100%;object-fit:cover;display:block;" onerror="this.style.display='none'">` : '<span style="font-size:1.8rem">🛍️</span>'}            </div>            <div class="cart-item-details" style="flex:1;min-width:0;">                <div class="cart-item-title">${item.title}</div>                <div class="cart-item-price">${formatNum(item.price)} دج</div>                <div class="cart-item-controls" style="display:flex;align-items:center;gap:0.5rem;margin-top:0.4rem;">                    <button class="qty-btn" onclick="changeCartQty('${item.id}',-1)">−</button>                    <span class="qty-display">${item.quantity}</span>                    <button class="qty-btn" onclick="changeCartQty('${item.id}',1)">+</button>                    <button class="btn btn-danger btn-sm" style="margin-right:0.5rem" onclick="removeFromCart('${item.id}')">                        <i class="fas fa-trash"></i>                    </button>                </div>            </div>            <div style="font-weight:700;color:var(--color-gold-primary);white-space:nowrap;flex-shrink:0;">                ${formatNum(item.price * item.quantity)} دج            </div>        </div>    `).join('') + `        <div class="cart-summary">            <div style="display:flex;justify-content:space-between;font-size:1rem;font-weight:700">                <span>المجموع الجزئي</span>                <span style="color:var(--color-gold-primary)">${formatNum(subtotal)} دج</span>            </div>            <div style="font-size:0.78rem;color:rgba(224,224,224,0.5);margin-top:0.3rem">+ رسوم التوصيل تُحسب عند إتمام الطلب</div>        </div>`;    if (footer) footer.style.display = 'flex';}function changeCartQty(productId, delta) {    const item = cart.find(c => c.id === productId);    if (!item) return;    item.quantity = Math.max(1, Math.min(10, item.quantity + delta));    localStorage.setItem('zn_cart', JSON.stringify(cart));    updateCartBadge();    renderCart();}function removeFromCart(productId) {    cart = cart.filter(c => c.id !== productId);    localStorage.setItem('zn_cart', JSON.stringify(cart));    updateCartBadge();    renderCart();    playSound('click');}// ======= Checkout =======function openCheckout() {    playSound('click');    if (!cart.length) { showToast('السلة فارغة', 'error'); return; }    if (currentUser) {        const nameEl  = document.getElementById('checkoutName');        const phoneEl = document.getElementById('checkoutPhone');        if (nameEl  && !nameEl.value)  nameEl.value  = currentUser.name  || '';        if (phoneEl && !phoneEl.value) phoneEl.value = currentUser.phone || '';    }    selectedDelivery = ''; selectedPayment = ''; selectedNetwork = '';    const elems = ['deliveryOfficeOpt','deliveryHomeOpt'];    elems.forEach(id => document.getElementById(id)?.classList.remove('selected'));    const ccpEl   = document.getElementById('ccpDetails');    const flexiEl = document.getElementById('flexiDetails');    const addrEl  = document.getElementById('addressGroup');    if (ccpEl)   ccpEl.style.display   = 'none';    if (flexiEl) flexiEl.style.display = 'none';    if (addrEl)  addrEl.style.display  = 'none';    updateCheckoutSummary();    closeModal('cartModal');    setTimeout(() => openModal('checkoutModal'), 150);}function updateCheckoutSummary() {    const container = document.getElementById('checkoutSummary');    if (!container) return;    const subtotal   = cart.reduce((s, c) => s + c.price * c.quantity, 0);    const wilaya     = document.getElementById('checkoutWilaya')?.value;    const wData      = getWilayaData(wilaya);    const shipping   = selectedDelivery === 'office' ? (wData?.office || 0) : selectedDelivery === 'home' ? (wData?.home || 0) : 0;    const total      = subtotal + shipping;    container.innerHTML = `        <div style="background:rgba(212,175,55,0.04);border:1px solid rgba(212,175,55,0.15);border-radius:10px;padding:1rem">            <div style="font-weight:700;color:var(--color-gold-primary);margin-bottom:0.75rem;font-size:0.9rem">📋 ملخص الطلب</div>            ${cart.map(c => `<div style="display:flex;justify-content:space-between;font-size:0.82rem;margin-bottom:0.3rem;color:rgba(224,224,224,0.8)">                <span>${c.title} ×${c.quantity}</span>                <span>${formatNum(c.price * c.quantity)} دج</span>            </div>`).join('')}            <div style="border-top:1px solid rgba(212,175,55,0.15);margin:0.75rem 0;padding-top:0.5rem">                <div style="display:flex;justify-content:space-between;font-size:0.85rem;margin-bottom:0.3rem">                    <span style="color:rgba(224,224,224,0.6)">المجموع الجزئي</span>                    <span>${formatNum(subtotal)} دج</span>                </div>                <div style="display:flex;justify-content:space-between;font-size:0.85rem;margin-bottom:0.5rem">                    <span style="color:rgba(224,224,224,0.6)">التوصيل</span>                    <span>${shipping > 0 ? formatNum(shipping) + ' دج' : (selectedDelivery ? '0 دج' : '—')}</span>                </div>                <div style="display:flex;justify-content:space-between;font-size:1.05rem;font-weight:800">                    <span>المجموع الكلي</span>                    <span style="color:var(--color-gold-primary)">${formatNum(total)} دج</span>                </div>            </div>        </div>`;}async function submitOrder() {    const name     = document.getElementById('checkoutName')?.value.trim();    const phone    = document.getElementById('checkoutPhone')?.value.trim();    const wilaya   = document.getElementById('checkoutWilaya')?.value;    const address  = document.getElementById('checkoutAddress')?.value.trim();    const notes    = document.getElementById('checkoutNotes')?.value.trim();    if (!name)            { showToast('الاسم مطلوب', 'error'); return; }    if (!phone)           { showToast('رقم الهاتف مطلوب', 'error'); return; }    if (!wilaya)          { showToast('اختر الولاية', 'error'); return; }    if (!selectedDelivery){ showToast('اختر نوع التوصيل', 'error'); return; }    if (selectedDelivery === 'home' && !address) { showToast('العنوان مطلوب للتوصيل للمنزل', 'error'); return; }    if (!cart.length)     { showToast('السلة فارغة', 'error'); return; }    const wData    = getWilayaData(wilaya);    const shipping = selectedDelivery === 'office' ? (wData?.office || 0) : (wData?.home || 0);    const subtotal = cart.reduce((s, c) => s + c.price * c.quantity, 0);    const total    = subtotal + shipping;    const items = cart.map(c => ({        id: c.id, title: c.title, price: c.price,        quantity: c.quantity, image: c.image || ''    }));    const btn = document.getElementById('confirmOrderBtn');    btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> جاري الإرسال...';    try {        const res = await apiCall({            action:          'createOrder',            customer_name:   name,            customer_phone:  phone,            wilaya,            delivery_type:   selectedDelivery,            address:         address || '',            payment_method:  'cod',            notes:           notes || '',            items:           JSON.stringify(items),            shipping_cost:   shipping,            subtotal,            total        });        if (res.success) {            playSound('cashier');            launchConfetti();            cart = []; localStorage.removeItem('zn_cart');            updateCartBadge();            closeModal('checkoutModal');            const idEl = document.getElementById('orderSuccessId');            if (idEl) idEl.textContent = 'رقم الطلب: #' + (res.data.order_id || '').slice(-8).toUpperCase();            openModal('orderSuccessModal');        } else { showToast(res.message || 'فشل إرسال الطلب', 'error'); }    } catch(e) { showToast('خطأ في الاتصال، تحقق من الإنترنت', 'error'); }    finally { btn.disabled = false; btn.innerHTML = '<i class="fas fa-check-circle"></i> تأكيد الطلبية'; }}// ======= طلباتي =======async function loadMyOrders() {    const list = document.getElementById('ordersList');    if (!list) return;    list.innerHTML = '<div class="empty-state"><div class="loading-spinner"></div></div>';    try {        const res = await apiCall({ action: 'getMyOrders' });        if (res.success) {            const orders = res.data.orders || [];            if (!orders.length) {                list.innerHTML = `<div class="empty-state"><div class="empty-icon">📦</div><div class="empty-title">لا توجد طلبات</div><div class="empty-desc">ابدأ بإضافة منتجات للسلة</div></div>`;            } else {                list.innerHTML = orders.map(o => renderOrderCard(o)).join('');            }        }    } catch(e) { showToast('خطأ في تحميل الطلبات', 'error'); }}const statusLabel = { pending:'قيد الانتظار', confirmed:'مؤكد', shipping:'جاري التوصيل', delivered:'تم التوصيل', rejected:'مرفوض', returned:'مُعاد', cancelled:'ملغي' };const statusColor = { pending:'#f59e0b', confirmed:'#3b82f6', shipping:'#8b5cf6', delivered:'#10b981', rejected:'#ef4444', returned:'#6b7280', cancelled:'#6b7280' };function renderOrderCard(o) {    const color = statusColor[o.status] || '#9ca3af';    const label = statusLabel[o.status] || o.status;    const itemsText = (o.items || []).map(i => `${i.title} ×${i.quantity}`).join(' | ');    return `        <div class="order-card" onclick="openOrderDetail('${o.id}')">            <div class="order-card-header">                <div>                    <div style="font-size:0.75rem;color:rgba(224,224,224,0.5);font-family:monospace">#${o.id.slice(-8).toUpperCase()}</div>                    <div style="font-size:0.78rem;color:rgba(224,224,224,0.5)">${formatDate(o.created_at)}</div>                </div>                <span class="order-status" style="background:${color}22;color:${color};border:1px solid ${color}44;padding:0.2rem 0.7rem;border-radius:50px;font-size:0.75rem;font-weight:700">${label}</span>            </div>            <div class="order-card-items" style="font-size:0.82rem;color:rgba(224,224,224,0.7);margin:0.5rem 0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${itemsText}</div>            <div class="order-card-footer">                <span style="font-weight:800;color:var(--color-gold-primary);font-size:1rem">${formatNum(o.total)} دج</span>                <span style="font-size:0.78rem;color:rgba(224,224,224,0.5)">${o.wilaya} — ${o.delivery_type === 'home' ? '🏠 منزل' : '🏢 مكتب'}</span>            </div>        </div>`;}async function openOrderDetail(orderId) {    playSound('click');    try {        const res = await apiCall({ action: 'getMyOrders' });        if (!res.success) return;        const o = (res.data.orders || []).find(x => x.id === orderId);        if (!o) return;        const totalQty  = (o.items || []).reduce((s, i) => s + (i.quantity || 1), 0);        const color     = statusColor[o.status] || '#9ca3af';        const label     = statusLabel[o.status]  || o.status;        const itemsHtml = (o.items || []).map(item => `            <div style="display:flex;align-items:center;gap:0.75rem;padding:0.6rem 0;border-bottom:1px solid rgba(212,175,55,0.06)">                ${item.image ? `<img src="${item.image}" style="width:48px;height:48px;object-fit:cover;border-radius:6px;border:1px solid rgba(212,175,55,0.2);flex-shrink:0" onerror="this.style.display='none'">` : ''}                <div style="flex:1;min-width:0">                    <div style="font-weight:600;font-size:0.85rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${item.title}</div>                    <div style="font-size:0.78rem;color:rgba(212,175,55,0.7)">${formatNum(item.price)} دج × ${item.quantity} = <strong style="color:var(--color-gold-primary)">${formatNum(item.price * item.quantity)} دج</strong></div>                </div>            </div>`).join('');        document.getElementById('orderDetailContent').innerHTML = `            <div style="text-align:center;padding:1rem 0 0.5rem">                <span style="background:${color}22;color:${color};border:1px solid ${color}44;padding:0.3rem 1rem;border-radius:50px;font-weight:700;font-size:0.9rem">${label}</span>                <div style="font-size:0.75rem;color:rgba(224,224,224,0.4);margin-top:0.4rem;font-family:monospace">#${o.id.slice(-8).toUpperCase()}</div>            </div>            <div style="background:var(--color-black-dark);border:var(--border-gold);border-radius:10px;padding:1rem;margin-bottom:0.75rem">                <div style="font-size:0.8rem;font-weight:700;color:rgba(212,175,55,0.7);margin-bottom:0.6rem">👤 معلومات الاستلام</div>                <div style="font-size:0.85rem;display:grid;gap:0.35rem">                    <div style="display:flex;justify-content:space-between"><span style="color:rgba(224,224,224,0.55)">الاسم</span><span style="font-weight:600">${o.customer_name}</span></div>                    <div style="display:flex;justify-content:space-between"><span style="color:rgba(224,224,224,0.55)">الهاتف</span><span dir="ltr">${o.customer_phone}</span></div>                    <div style="display:flex;justify-content:space-between"><span style="color:rgba(224,224,224,0.55)">الولاية</span><span>${o.wilaya}</span></div>                    <div style="display:flex;justify-content:space-between"><span style="color:rgba(224,224,224,0.55)">التوصيل</span><span>${o.delivery_type === 'home' ? '🏠 منزل' : '🏢 مكتب'}</span></div>                    ${o.address ? `<div style="display:flex;justify-content:space-between;gap:1rem"><span style="color:rgba(224,224,224,0.55);flex-shrink:0">العنوان</span><span style="text-align:left">${o.address}</span></div>` : ''}                    ${o.notes ? `<div style="display:flex;justify-content:space-between;gap:1rem"><span style="color:rgba(224,224,224,0.55);flex-shrink:0">ملاحظات</span><span>${o.notes}</span></div>` : ''}                </div>            </div>            <div style="background:rgba(16,185,129,0.06);border:1px solid rgba(16,185,129,0.25);border-radius:10px;padding:0.85rem;margin-bottom:0.75rem">                <div style="font-size:0.8rem;font-weight:700;color:#10b981;margin-bottom:0.3rem">💵 الدفع</div>                <div style="font-size:0.85rem;font-weight:600;color:#10b981">الدفع عند الاستلام</div>            </div>            <div style="background:var(--color-black-dark);border:var(--border-gold);border-radius:10px;padding:1rem;margin-bottom:0.75rem">                <div style="font-size:0.8rem;font-weight:700;color:rgba(212,175,55,0.7);margin-bottom:0.6rem">🛍️ المنتجات (${totalQty} قطعة)</div>                ${itemsHtml}                <div style="margin-top:0.75rem;padding-top:0.75rem;border-top:1px solid rgba(212,175,55,0.1)">                    <div style="display:flex;justify-content:space-between;font-size:0.83rem;margin-bottom:0.25rem">                        <span style="color:rgba(224,224,224,0.55)">المنتجات</span><span>${formatNum(o.subtotal || 0)} دج</span>                    </div>                    <div style="display:flex;justify-content:space-between;font-size:0.83rem;margin-bottom:0.4rem">                        <span style="color:rgba(224,224,224,0.55)">التوصيل</span><span>${formatNum(o.shipping_cost || 0)} دج</span>                    </div>                    <div style="display:flex;justify-content:space-between;font-size:1.05rem;font-weight:800">                        <span>الإجمالي</span><span style="color:var(--color-gold-primary)">${formatNum(o.total)} دج</span>                    </div>                </div>            </div>            ${o.rejection_reason ? `<div style="background:rgba(239,68,68,0.08);border:1px solid rgba(239,68,68,0.3);border-radius:10px;padding:0.85rem;margin-bottom:0.75rem">                <div style="font-size:0.8rem;font-weight:700;color:#ef4444;margin-bottom:0.3rem">❌ سبب الرفض</div>                <div style="font-size:0.85rem">${o.rejection_reason}</div>            </div>` : ''}        `;        const footer = document.getElementById('orderDetailFooter');        footer.innerHTML = `<button class="btn btn-secondary" onclick="closeModal('orderDetailModal')">إغلاق</button>`;        if (o.status === 'pending') {            footer.innerHTML += `                <button class="btn btn-primary btn-sm" onclick="openEditOrderModal('${o.id}');closeModal('orderDetailModal')">                    <i class="fas fa-edit"></i> تعديل                </button>                <button class="btn btn-danger btn-sm" onclick="cancelOrder('${o.id}');closeModal('orderDetailModal')">                    <i class="fas fa-times"></i> إلغاء                </button>`;        }        if (o.status === 'delivered') {            footer.innerHTML += `<button class="btn btn-primary btn-sm" onclick="openRatingFromOrder('${o.id}')">                <i class="fas fa-star"></i> تقييم            </button>`;        }        openModal('orderDetailModal');    } catch(e) { showToast('خطأ في تحميل التفاصيل', 'error'); }}async function cancelOrder(orderId) {    if (!confirm('هل تريد إلغاء هذا الطلب؟')) return;    try {        const res = await apiCall({ action: 'cancelOrder', order_id: orderId });        if (res.success) { showToast('تم إلغاء الطلب', 'success'); loadMyOrders(); }        else { showToast(res.message || 'خطأ', 'error'); }    } catch(e) { showToast('خطأ', 'error'); }}function openEditOrderModal(orderId) {    currentEditOrderId = orderId;    openModal('editOrderModal');}async function submitEditOrder() {    const name  = document.getElementById('editOrderName').value.trim();    const phone = document.getElementById('editOrderPhone').value.trim();    const notes = document.getElementById('editOrderNotes').value.trim();    const btn = document.getElementById('editOrderBtn');    btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';    try {        const res = await apiCall({ action: 'editOrder', order_id: currentEditOrderId, customer_name: name, customer_phone: phone, notes });        if (res.success) { showToast('تم التعديل', 'success'); closeModal('editOrderModal'); loadMyOrders(); }        else { showToast(res.message || 'خطأ', 'error'); }    } catch(e) { showToast('خطأ', 'error'); }    finally { btn.disabled = false; btn.innerHTML = '<i class="fas fa-save"></i> حفظ التعديلات'; }}// ======= المحفظة =======async function loadWallet() {    try {        const res = await apiCall({ action: 'getWalletBalance' });        if (!res.success) return;        const d = res.data;        animateNumber(document.getElementById('walletBalance'),  0, d.balance         || 0, 1000);        animateNumber(document.getElementById('totalEarned'),    0, d.total_earned    || 0, 800);        animateNumber(document.getElementById('totalWithdrawn'), 0, d.total_withdrawn || 0, 800);        animateNumber(document.getElementById('totalOrders'),    0, d.orders_count    || 0, 600);        document.getElementById('withdrawAvailable').textContent = formatNum(d.balance || 0) + ' دج';        const bal       = d.balance || 0;        const earned    = d.total_earned || 0;        const levelInfo = d.level || {};        const userLevel = d.user_level || 'none';        renderUserLevelBadge(userLevel);        const nextMin = levelInfo.next_min || 4000;        const progEl  = document.getElementById('walletProgressWrap');        if (progEl) {            const pct = Math.min(100, Math.round((earned / nextMin) * 100));            const nextLabel = {                bronze:'الذهبي (40,000 دج)', gold:'الألماسي (100,000 دج)', diamond:'أعلى مستوى! 💎', none:'البرونزي (4,000 دج)'            }[userLevel] || 'البرونزي';            progEl.innerHTML = `                <div style="background:var(--color-black-dark);border:var(--border-gold);border-radius:10px;padding:1rem;margin-bottom:1.25rem">                    <div style="display:flex;justify-content:space-between;font-size:0.8rem;margin-bottom:0.6rem">                        <span style="color:rgba(224,224,224,0.6)">نحو ${nextLabel}</span>                        <span style="color:var(--color-gold-primary);font-weight:700">${pct}%</span>                    </div>                    <div style="height:8px;background:rgba(212,175,55,0.1);border-radius:4px;overflow:hidden">                        <div style="height:100%;width:${pct}%;background:linear-gradient(135deg,#b8941e,#ffd700);border-radius:4px;transition:width 1s ease"></div>                    </div>                    <div style="margin-top:0.5rem;text-align:center;font-size:0.78rem;color:${bal >= 4000 ? '#10b981' : 'rgba(224,224,224,0.5)'}">                        ${bal >= 4000 ? '✅ يمكنك طلب السحب الآن!' : `تحتاج ${formatNum(4000 - bal)} دج إضافية للسحب`}                    </div>                </div>`;        }        ['bronze','gold','diamond'].forEach(lvl => {            const card = document.getElementById('walletLevel' + lvl.charAt(0).toUpperCase() + lvl.slice(1));            if (card) {                card.style.opacity   = userLevel === lvl ? '1' : '0.5';                card.style.transform = userLevel === lvl ? 'scale(1.02)' : 'scale(1)';            }        });        renderPaymentMethods(d.payment_methods || []);        populateWithdrawMethods(d.payment_methods || []);        loadWithdrawals();    } catch(e) {}}function renderPaymentMethods(methods) {    const container = document.getElementById('paymentMethodsList');    if (!container) return;    if (!methods.length) {        container.innerHTML = `<div style="text-align:center;padding:1rem;color:rgba(224,224,224,.5);font-size:.85rem">لا توجد طرق سحب مضافة</div>`;        return;    }    container.innerHTML = methods.map(m => `        <div class="payment-method-card">            <div class="payment-method-icon">${m.type === 'ccp' ? '🏦' : '📱'}</div>            <div class="payment-method-info">                <div class="payment-method-type">${m.type === 'ccp' ? 'CCP' : 'فليكسي'}</div>                <div class="payment-method-details">${m.details}</div>            </div>            <button class="btn btn-danger btn-sm" onclick="deletePaymentMethod('${m.id}')"><i class="fas fa-trash"></i></button>        </div>`).join('');}function populateWithdrawMethods(methods) {    const sel = document.getElementById('withdrawMethod');    if (!sel) return;    sel.innerHTML = '<option value="">-- اختر طريقة الاستلام --</option>';    methods.forEach(m => {        sel.innerHTML += `<option value="${m.id}">${m.type === 'ccp' ? '🏦 CCP' : '📱 فليكسي'}: ${m.details}</option>`;    });}function openAddPaymentModal() {    playSound('click');    ['addPayCCPOpt','addPayFlexiOpt'].forEach(id => document.getElementById(id)?.classList.remove('selected'));    ['addPayCCPDetails','addPayFlexiDetails'].forEach(id => { const el = document.getElementById(id); if(el) el.style.display = 'none'; });    const ccpEl = document.getElementById('addCCPNumber'); if(ccpEl) ccpEl.value = '';    const flEl  = document.getElementById('addFlexiPhone'); if(flEl) flEl.value = '';    selectedNetwork2 = '';    openModal('addPaymentModal');}function selectAddPayType(type) {    ['addPayCCPOpt','addPayFlexiOpt'].forEach(id => document.getElementById(id)?.classList.remove('selected'));    document.getElementById(type === 'ccp' ? 'addPayCCPOpt' : 'addPayFlexiOpt')?.classList.add('selected');    document.getElementById('addPayCCPDetails').style.display   = type === 'ccp'   ? 'block' : 'none';    document.getElementById('addPayFlexiDetails').style.display = type === 'flexi' ? 'block' : 'none';}function selectNetwork2(name, el) {    selectedNetwork2 = name;    document.querySelectorAll('#addPayFlexiDetails .network-option').forEach(n => n.classList.remove('selected'));    el.classList.add('selected');}async function submitAddPayment() {    const type  = document.querySelector('input[name="addPayType"]:checked')?.value;    let details = '';    if (type === 'ccp') {        details = document.getElementById('addCCPNumber').value.trim();        if (!details) { showToast('أدخل رقم CCP', 'error'); return; }    } else if (type === 'flexi') {        const phone = document.getElementById('addFlexiPhone').value.trim();        if (!selectedNetwork2) { showToast('اختر الشبكة', 'error'); return; }        if (!phone) { showToast('أدخل رقم الهاتف', 'error'); return; }        details = selectedNetwork2 + ' — ' + phone;    } else { showToast('اختر طريقة السحب', 'error'); return; }    try {        const res = await apiCall({ action: 'addPaymentMethod', type, details });        if (res.success) { showToast('تمت الإضافة', 'success'); closeModal('addPaymentModal'); loadWallet(); }        else { showToast(res.message || 'خطأ', 'error'); }    } catch(e) { showToast('خطأ', 'error'); }}async function deletePaymentMethod(methodId) {    if (!confirm('هل تريد حذف طريقة السحب؟')) return;    try {        const res = await apiCall({ action: 'deletePaymentMethod', method_id: methodId });        if (res.success) { showToast('تم الحذف', 'success'); loadWallet(); }        else { showToast(res.message || 'خطأ', 'error'); }    } catch(e) { showToast('خطأ', 'error'); }}function openWithdrawalModal() {    playSound('click');    openModal('withdrawalModal');}async function submitWithdrawal() {    const amount   = parseFloat(document.getElementById('withdrawAmount').value);    const methodId = document.getElementById('withdrawMethod').value;    if (!amount || amount < 4000) { showToast('الحد الأدنى للسحب 4,000 دج', 'error'); return; }    if (!methodId) { showToast('اختر طريقة الاستلام', 'error'); return; }    try {        const res = await apiCall({ action: 'requestWithdrawal', amount, method_id: methodId });        if (res.success) { showToast('تم إرسال طلب السحب ✅', 'success'); closeModal('withdrawalModal'); loadWallet(); }        else { showToast(res.message || 'خطأ', 'error'); }    } catch(e) { showToast('خطأ', 'error'); }}async function loadWithdrawals() {    const list = document.getElementById('withdrawalsList');    if (!list) return;    try {        const res = await apiCall({ action: 'getWithdrawals' });        if (res.success) {            const ws = res.data.withdrawals || [];            if (!ws.length) { list.innerHTML = `<div style="text-align:center;padding:1rem;color:rgba(224,224,224,0.4);font-size:0.85rem">لا توجد سحوبات</div>`; return; }            const wColors = { pending:'#f59e0b', paid:'#10b981', rejected:'#ef4444' };            const wLabels = { pending:'قيد المعالجة', paid:'تم الصرف', rejected:'مرفوض' };            list.innerHTML = ws.map(w => `                <div style="display:flex;justify-content:space-between;align-items:center;padding:0.75rem;background:var(--color-black-dark);border:var(--border-gold);border-radius:8px;margin-bottom:0.5rem;font-size:0.85rem">                    <div>                        <div style="font-weight:700;color:var(--color-gold-primary)">${formatNum(w.amount)} دج</div>                        <div style="font-size:0.75rem;color:rgba(224,224,224,0.5)">${w.method_type === 'ccp' ? '🏦 CCP' : '📱 فليكسي'} — ${formatDate(w.created_at)}</div>                    </div>                    <span style="background:${wColors[w.status]||'#6b7280'}22;color:${wColors[w.status]||'#6b7280'};border:1px solid ${wColors[w.status]||'#6b7280'}44;padding:0.2rem 0.6rem;border-radius:50px;font-size:0.72rem;font-weight:700">${wLabels[w.status]||w.status}</span>                </div>`).join('');        }    } catch(e) {}}// ======= أسعار التوصيل =======function openShippingModal() {    playSound('click');    renderShippingTable('shippingTableModal');    openModal('shippingModal');}function loadShippingInHowto() {    renderShippingTable('shippingTableHowto');}function renderShippingTable(containerId) {    const container = document.getElementById(containerId);    if (!container) return;    if (!shippingData.length) {        container.innerHTML = '<div style="text-align:center;padding:1rem;color:rgba(224,224,224,0.4)">لا توجد بيانات</div>';        return;    }    container.innerHTML = shippingData.map(w => `        <div class="shipping-row">            <span class="shipping-wilaya">${w.name}</span>            <span class="shipping-price">${w.office !== null ? formatNum(w.office) + '/' : '—/'}${w.home !== null ? formatNum(w.home) : '—'} دج</span>        </div>`).join('');}// ======= الإشعارات =======async function loadNotifCount() {    try {        const res = await apiCall({ action: 'getUnreadNotificationsCount' });        if (res.success) {            const c = res.data.count || 0;            const el  = document.getElementById('notifBadge');            const nav = document.getElementById('navNotifBadge');            if (el)  { el.textContent  = c; el.style.display  = c > 0 ? 'flex' : 'none'; }            if (nav) { nav.textContent = c; nav.style.display = c > 0 ? 'flex' : 'none'; }            // إشعار المتصفح عند وصول إشعارات جديدة            if (c > lastNotifCount && lastNotifCount > 0) {                showToast(`🔔 لديك ${c} إشعار جديد`, 'info');            }            lastNotifCount = c;        }    } catch(e) {}}async function loadNotifications() {    const list = document.getElementById('notificationsList');    if (!list) return;    list.innerHTML = '<div class="empty-state"><div class="loading-spinner"></div></div>';    try {        const res = await apiCall({ action: 'getUserNotifications' });        if (res.success) {            const notifs = res.data.notifications || [];            if (!notifs.length) {                list.innerHTML = `<div class="empty-state"><div class="empty-icon">🔔</div><div class="empty-title">لا توجد إشعارات</div></div>`;            } else {                const typeIcons = { order:'📦', wallet:'💰', info:'ℹ️', system:'⚙️' };                list.innerHTML = notifs.map(n => `                    <div class="notification-item ${n.read ? '' : 'unread'}" onclick="markRead('${n.id}',this)">                        <div class="notif-icon">${typeIcons[n.type] || '🔔'}</div>                        <div class="notif-content">                            <div class="notif-title">${n.title}</div>                            <div class="notif-message">${n.message}</div>                            <div class="notif-time">${formatDate(n.created_at)}</div>                        </div>                    </div>`).join('');            }        }    } catch(e) {}}async function markRead(notifId, el) {    el?.classList.remove('unread');    try { await apiCall({ action: 'markNotificationAsRead', notification_id: notifId }); loadNotifCount(); } catch(e) {}}async function markAllNotificationsRead() {    try { await apiCall({ action: 'markNotificationAsRead', all: '1' }); loadNotifications(); loadNotifCount(); } catch(e) {}}// ======= الملف الشخصي =======async function refreshProfile() {    try {        const res = await apiCall({ action: 'getUserData' });        if (res.success) { currentUser = res.data.user; updateUserUI(); }    } catch(e) {}}function openEditProfileModal() {    playSound('click');    document.getElementById('editName').value = currentUser?.name || '';    openModal('editProfileModal');}async function submitEditProfile() {    const name = document.getElementById('editName').value.trim();    if (!name) { showToast('الاسم مطلوب', 'error'); return; }    try {        const res = await apiCall({ action: 'updateUser', name });        if (res.success) {            if (currentUser) currentUser.name = name;            updateUserUI();            showToast('تم التحديث', 'success');            closeModal('editProfileModal');        } else { showToast(res.message || 'خطأ', 'error'); }    } catch(e) { showToast('خطأ', 'error'); }}function openChangePasswordModal() {    playSound('click');    ['currentPassword','newPass','newPassConfirm'].forEach(id => { const el = document.getElementById(id); if(el) el.value = ''; });    openModal('changePasswordModal');}async function submitChangePassword() {    const cur  = document.getElementById('currentPassword').value;    const nw   = document.getElementById('newPass').value;    const conf = document.getElementById('newPassConfirm').value;    if (!cur || !nw) { showToast('يرجى ملء الحقول', 'error'); return; }    if (nw !== conf) { showToast('كلمتا المرور غير متطابقتين', 'error'); return; }    if (nw.length < 6) { showToast('كلمة المرور قصيرة', 'error'); return; }    try {        const res = await apiCall({ action: 'changePassword', current_password: cur, new_password: nw });        if (res.success) { showToast('تم تغيير كلمة المرور', 'success'); closeModal('changePasswordModal'); }        else { showToast(res.message || 'خطأ', 'error'); }    } catch(e) { showToast('خطأ', 'error'); }}async function openLinkTelegramModal() {    playSound('click');    openModal('linkTelegramModal');    await refreshTelegramCode();}async function refreshTelegramCode() {    try {        const res = await apiCall({ action: 'getTelegramLinkCode' });        if (res.success) { document.getElementById('telegramLinkCode').textContent = res.data.code || '------'; }    } catch(e) {}}// ======= البحث =======function handleSearch(query) {    clearTimeout(searchTimeout);    if (query.length < 1) { document.getElementById('searchGrid').innerHTML = ''; return; }    searchTimeout = setTimeout(() => performSearch(query), 400);}async function performSearch(query) {    try {        const res = await apiCall({ action: 'searchProducts', q: query });        if (res.success) {            const prods = res.data.products || [];            const grid  = document.getElementById('searchGrid');            const empty = document.getElementById('searchEmpty');            const count = document.getElementById('searchCount');            if (count) count.textContent = prods.length + ' نتيجة';            if (!prods.length) {                grid.innerHTML = '';                if (empty) empty.style.display = 'block';            } else {                if (empty) empty.style.display = 'none';                grid.innerHTML = prods.map(p => createProductCard(p)).join('');            }        }    } catch(e) {}}// ======= التقييم =======function openRatingFromOrder(orderId) {    currentRatingOrderId = orderId;    openModal('ratingModal');}function setRating(val) {    selectedRating = val;    document.querySelectorAll('#ratingStarsInput .star').forEach((s, i) => {        s.classList.toggle('active', i < val);        s.style.color = i < val ? '#ffd700' : 'rgba(224,224,224,0.3)';    });}async function submitRating() {    if (!selectedRating) { showToast('اختر تقييمك', 'error'); return; }    const comment = document.getElementById('ratingComment').value.trim();    showToast('شكراً على تقييمك! ⭐', 'success');    closeModal('ratingModal');}// ======= المودالات =======function openModal(id) {    playSound('click');    const el = document.getElementById(id);    if (!el) return;    el.classList.add('active');    document.body.style.overflow = 'hidden';}function closeModal(id) {    const el = document.getElementById(id);    if (!el) return;    el.classList.remove('active');    if (!document.querySelector('.modal-overlay.active')) {        document.body.style.overflow = '';    }}function closeModalOnOverlay(event, id) {    if (event.target === document.getElementById(id)) closeModal(id);}// ======= كونفيتي =======function launchConfetti() {    try {        const end = Date.now() + 2500;        (function frame() {            confetti({ particleCount: 3, angle: 60, spread: 55, origin: { x: 0 }, colors: ['#d4af37','#ffd700','#fff'] });            confetti({ particleCount: 3, angle: 120, spread: 55, origin: { x: 1 }, colors: ['#d4af37','#ffd700','#fff'] });            if (Date.now() < end) requestAnimationFrame(frame);        })();    } catch(e) {}}// ======= أدوات =======function animateNumber(el, from, to, duration) {    if (!el) return;    const start = performance.now();    const update = (now) => {        const elapsed  = now - start;        const progress = Math.min(elapsed / duration, 1);        const eased    = 1 - Math.pow(1 - progress, 3);        el.textContent = formatNum(Math.round(from + (to - from) * eased));        if (progress < 1) requestAnimationFrame(update);    };    requestAnimationFrame(update);}function formatNum(n) {    return Number(n || 0).toLocaleString('ar-DZ');}function formatDate(dateStr) {    if (!dateStr) return '-';    try {        const d = new Date(dateStr);        return d.toLocaleDateString('ar-DZ') + ' ' + d.toLocaleTimeString('ar-DZ', { hour: '2-digit', minute: '2-digit' });    } catch(e) { return dateStr; }}// ======================================================//   التهيئة الرئيسية — MySQL Token Fix//   الاعتماد الكامل على MySQL للتوكنات// ======================================================window.addEventListener('DOMContentLoaded', async () => {    initSounds();    // === Wake-up Ping — ننتظره قبل أي شيء ===    try { await apiCallOnce({ action: 'ping' }, 20000); } catch(e) {}    try {        let loggedIn = false;        const savedToken = localStorage.getItem('zn_auth_token');        if (savedToken) {            try {                const tokenRes = await apiCall({ action: 'loginWithToken', auth_token: savedToken });                if (tokenRes.success) {                    currentUser = tokenRes.data.user;                    loggedIn = true;                } else {                    // السيرفر رفض التوكن نهائياً — احذفه وأعرض تسجيل الدخول                    localStorage.removeItem('zn_auth_token');                    // أبقِ الهاتف محفوظاً للراحة                }            } catch(e) {                // ===== الإصلاح الجذري =====                // فشل الشبكة: لا تحذف التوكن، أعرض زر "إعادة المحاولة"                // بدلاً من "خطأ في الاتصال" المزعج                hideLoading();                showRetryScreen(savedToken);                return; // لا تكمل التحميل            }        }        // احتياطي: Session        if (!loggedIn) {            try {                const res = await apiCall({ action: 'getUserData' });                if (res.success && res.data.user) {                    currentUser = res.data.user;                    loggedIn = true;                }            } catch(e) {}        }        if (loggedIn) {            await showApp();        } else {            const savedPhone = localStorage.getItem('zn_auth_phone');            if (savedPhone) {                const phoneEl = document.getElementById('loginPhone');                if (phoneEl) phoneEl.value = savedPhone;                const rememberEl = document.getElementById('rememberMe');                if (rememberEl && localStorage.getItem('zn_remember_me') === '1') {                    rememberEl.checked = true;                }            }            document.getElementById('authScreen').classList.remove('hidden');        }    } catch(e) {        document.getElementById('authScreen').classList.remove('hidden');    }    hideLoading();    updateCartBadge();    window.addEventListener('scroll', () => {        const btn = document.getElementById('backToTop');        if (btn) btn.style.display = window.scrollY > 300 ? 'flex' : 'none';    });    window.addEventListener('keydown', (e) => {        if (e.key === 'Escape') {            document.querySelectorAll('.modal-overlay.active').forEach(m => {                m.classList.remove('active');            });            document.body.style.overflow = '';        }    });});// ===== شاشة إعادة المحاولة الأنيقة =====// تظهر بدلاً من "خطأ في الاتصال" عند فشل الشبكةfunction showRetryScreen(savedToken) {    const ls = document.getElementById('loadingScreen');    if (ls) ls.remove();    const div = document.createElement('div');    div.id = 'retryScreen';    div.style.cssText = `        position:fixed;inset:0;background:#1a1a1a;display:flex;        flex-direction:column;align-items:center;justify-content:center;        z-index:9999;gap:20px;padding:30px;text-align:center;    `;    div.innerHTML = `        <div style="font-size:3rem">👋</div>        <h2 style="color:#ffd700;margin:0;font-size:1.5rem">مرحباً بعودتك!</h2>        <p style="color:#ccc;margin:0;font-size:0.9rem;max-width:280px;line-height:1.6">            اضغط للدخول لحسابك        </p>        <button id="retryBtn" onclick="clearCacheAndReload()" style="            background:#ffd700;color:#1a1a1a;border:none;padding:14px 35px;            border-radius:12px;font-size:1rem;font-weight:700;cursor:pointer;            font-family:inherit;        ">🚀 دخول</button>        <button onclick="forceShowLogin()" style="            background:transparent;color:#888;border:1px solid #444;            padding:10px 25px;border-radius:10px;font-size:0.85rem;            cursor:pointer;font-family:inherit;        ">تسجيل الدخول يدوياً</button>    `;    document.body.appendChild(div);    updateCartBadge();}async function clearCacheAndReload() {    const btn = document.getElementById('retryBtn');    if (btn) { btn.disabled = true; btn.textContent = '⏳ جاري التحديث...'; }    // احتفظ برقم الهاتف فقط    const savedPhone = localStorage.getItem('zn_auth_phone');    const rememberMe = localStorage.getItem('zn_remember_me');    // 1. مسح localStorage    localStorage.clear();    if (savedPhone) localStorage.setItem('zn_auth_phone', savedPhone);    if (rememberMe) localStorage.setItem('zn_remember_me', rememberMe);    // 2. مسح sessionStorage    sessionStorage.clear();    // 3. مسح Service Worker Cache (الأهم — يمسح JS/CSS/HTML المحفوظة)    try {        if ('caches' in window) {            const keys = await caches.keys();            await Promise.all(keys.map(key => caches.delete(key)));        }    } catch(e) {}    // 4. إلغاء تسجيل Service Workers    try {        if ('serviceWorker' in navigator) {            const regs = await navigator.serviceWorker.getRegistrations();            await Promise.all(regs.map(reg => reg.unregister()));        }    } catch(e) {}    // 5. إعادة تحميل الصفحة بدون cache    window.location.href = window.location.href.split('?')[0] + '?v=' + Date.now();}async function retryAutoLogin() {    const btn = document.getElementById('retryBtn');    const savedToken = localStorage.getItem('zn_auth_token');    if (!savedToken) { forceShowLogin(); return; }    if (btn) { btn.disabled = true; btn.textContent = '⏳ جاري الاتصال...'; }    // انتظر إيقاظ السيرفر أولاً    try { await apiCallOnce({ action: 'ping' }, 25000); } catch(e) {}    // حاول 5 مرات    for (let i = 1; i <= 5; i++) {        try {            if (btn) btn.textContent = `⏳ محاولة ${i} من 5...`;            const res = await apiCallOnce({ action: 'loginWithToken', auth_token: savedToken }, 25000);            if (res && res.success) {                currentUser = res.data.user;                document.getElementById('retryScreen')?.remove();                await showApp();                hideLoading();                updateCartBadge();                return;            } else {                // التوكن منتهي                localStorage.removeItem('zn_auth_token');                forceShowLogin();                return;            }        } catch(e) {            if (i < 5) {                if (btn) btn.textContent = `⏳ السيرفر يستيقظ... (${i}/5)`;                await new Promise(r => setTimeout(r, 5000));            }        }    }    // فشلت كل المحاولات    if (btn) { btn.disabled = false; btn.textContent = '🔄 إعادة المحاولة'; }    showToast('السيرفر يستيقظ... انتظر 30 ثانية وحاول مجدداً', 'warning');}function forceShowLogin() {    document.getElementById('retryScreen')?.remove();    const savedPhone = localStorage.getItem('zn_auth_phone');    if (savedPhone) {        const phoneEl = document.getElementById('loginPhone');        if (phoneEl) phoneEl.value = savedPhone;    }    document.getElementById('authScreen')?.classList.remove('hidden');    hideLoading();    updateCartBadge();}